def merge_intervals(intervals):
    if not intervals:
        return []

    sorted_intervals = intervals[:]
    sorted_intervals.sort(key=lambda x: x[0])

    merged = [sorted_intervals[0]]

    for current in sorted_intervals[1:]:
        prev = merged[-1]
        if current[0] <= prev[1]:
            prev[1] = max(prev[1], current[1])
        else:
            merged.append(current)

    return merged
```

